import java.util.*;

public class Test {
    int r, c;
    long[][] C = new long[64][64];
    long best = Long.MAX_VALUE;
    Scanner sca = new Scanner(System.in);
    char[] cs;
    Map<Long, Long> cache = new TreeMap<>();

    void buildComb() {
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{x, y, v1, v2});
        while (!stack.isEmpty()) {
            long[] cur = stack.pop();
            long cx = cur[0];
            long cy = cur[1];
            int a = (int) cur[2];
            int b = (int) cur[3];
            long d = Math.abs(cx - cy);
            if (best <= 1 || d - C[a][r] * C[b][r] >= best) continue;
            if (a == 0 && b == 0) {
                if (d < best) best = d;
                continue;
            }
            if (b > 0) {
                long dx = C[a][r] * (C[b][r] - C[b - 1][r]);
                stack.push(new long[]{cx + dx, cy, a, b - 1});
            }
            if (a > 0) {
                long dy = (C[a][r] - C[a - 1][r]) * C[b][r];
                stack.push(new long[]{cx, cy + dy, a - 1, b});
            }
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long key = x * 10000 + v1 * 100 + v2;
        Long cached = cache.get(key);
        if (cached != null) return cached;
        long ans = 0L;
        long d = Math.abs(x - y);
        if (d - C[v1][r] * C[v2][r] > best) {
            cache.put(key, ans);
            return ans;
        }
        if (v1 == 0 && v2 == 0) return 1L;
        char ch = cs[v1 + v2 - 1];
        if (v1 > 0 && ch != 'B') {
            long dy = (C[v1][r] - C[v1 - 1][r]) * C[v2][r];
            ans += solve(x, y + dy, v1 - 1, v2);
        }
        if (v2 > 0 && ch != 'A') {
            long dx = C[v1][r] * (C[v2][r] - C[v2 - 1][r]);
            ans += solve(x + dx, y, v1, v2 - 1);
        }
        cache.put(key, ans);
        return ans;
    }

    void run() {
        r = sca.nextInt();
        c = sca.nextInt();
        sca.nextLine();
        cs = sca.nextLine().toCharArray();
        buildComb();
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 > 0 && v2 > 0) {
            if (x > y) {
                long dy = (C[v1][r] - C[v1 - 1][r]) * C[v2][r];
                y += dy;
                v1--;
            } else {
                long dx = C[v1][r] * (C[v2][r] - C[v2 - 1][r]);
                x += dx;
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        System.out.println(solve(0, 0, r + c, r + c));
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
